// The site icon — the gift box illustration on the peach brand gradient —
// embedded directly as a base64 data URI rather than referenced by URL.
//
// This exists specifically because next/og's renderer (Satori) proved
// unreliable for icon rendering via two different runtime-fetch approaches:
// remotely fetching this same PNG by URL silently flattened its alpha
// channel onto white during compositing, and rendering a plain-text emoji
// character via the emoji: "twemoji" option (which fetches an SVG from an
// external CDN at request time) rendered incorrectly in production testing.
// A data URI has no network dependency at render time at all — the image
// data is part of the tree synchronously, nothing to fetch, nothing that
// can fail or get mangled in transit.
export const BRAND_ICON_DATA_URI = "data:image/png;base64,";

// The newer, standalone gift box icon (no colored badge/background baked
// in — just the icon itself with a transparent background), sourced from
// a design Cian provided directly. Used for opengraph-image.js, which
// switched to a flat site-background-color card and needed the icon
// rendered on its own rather than pre-composited onto a peach badge.
export const BRAND_ICON_OG_DATA_URI = "data:image/png;base64,";
